// Assembles src/content.js from content/part-NN.html (one file per study part).
// Edit the HTML files, then run:  npm run build:content
import fs from 'node:fs';

const files = fs.readdirSync('content').filter((f) => /^part-\d\d\.html$/.test(f)).sort();
const content = files.map((f) => ({ part: +f.slice(5, 7), html: fs.readFileSync('content/' + f, 'utf8').trim() }));
content.forEach((c, i) => { if (c.part !== i + 1) throw new Error('missing part ' + (i + 1)); });

fs.writeFileSync('src/content.js',
  '// GENERATED by tools/build-content.mjs from content/*.html - do not edit by hand.\n' +
  'export const CONTENT = ' + JSON.stringify(content, null, 1) + ';\n');
console.log('parts written:', content.length);
